/// Metadata about a single validated field, generated by `#[derive(RodValidate)]`.
///
/// This is exposed so that UI/form layers can introspect the validation rules
/// at compile time (see the [`RodMetadata`] trait and the helpers in
/// [`combinators::ValidationMetadata`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RodFieldMeta {
    /// The field name. For enum fields this is qualified as `Variant.field`
    /// (or `Variant.index` for unnamed tuple-style fields).
    pub name: &'static str,
    /// The `#[rod(group = "...")]` tag of the field, if any.
    pub group: Option<&'static str>,
    /// Whether the field participates unconditionally in validation.
    /// Fields with an `Option { ... }` rule are marked as not required,
    /// since a serde-serialized `null` is a valid representation for them.
    pub required: bool,
}

/// Static metadata about the fields of a validated type.
///
/// Implemented automatically by `#[derive(RodValidate)]`.
pub trait RodMetadata {
    /// Metadata for every (non-skipped) validated field, in declaration order.
    const FIELDS: &'static [RodFieldMeta];
}

pub trait RodValidate {
    /// Validate the struct, returning an error if validation fails.
    fn validate(&self) -> Result<(), errors::RodValidateError>;
    /// Validate the struct, returning a list of errors if validation fails.
    fn validate_all(&self) -> Result<(), errors::RodValidateErrorList>;
    /// Validate only the fields tagged with `#[rod(group = "name")]` matching
    /// the given group, plus every field that has no group.
    ///
    /// Types that don't use groups simply validate everything.
    fn validate_group(&self, _group: &str) -> Result<(), errors::RodValidateErrorList> {
        self.validate_all()
    }
    /// Validate every field, regardless of its group.
    fn validate_all_groups(&self) -> Result<(), errors::RodValidateErrorList> {
        self.validate_all()
    }
}

/// `check_all` runs a custom closure that reports **every** issue it finds,
/// instead of failing fast like a plain
/// `check = |x| bool` closure. Use it when one field can be wrong in several
/// ways and the user should see all of them at once:
///
/// ```rust
/// use rod_validation::prelude::*;
///
/// #[derive(RodValidate)]
/// struct Password {
///     #[rod(
///         String { length: 8..=30 },
///         check_all = |p: &String| {
///             let mut issues = Vec::new();
///             if !p.chars().any(|c| c.is_ascii_digit()) {
///                 issues.push("needs a digit");
///             }
///             if !p.chars().any(|c| c.is_ascii_uppercase()) {
///                 issues.push("needs an uppercase letter");
///             }
///             issues
///         }
///     )]
///     password: String,
/// }
///
/// let errors = Password { password: "lowercase".to_string() }.validate_all().unwrap_err();
/// assert_eq!(errors.len(), 2); // both issues, from one closure
/// ```
///
/// `check` and `check_all` are mutually exclusive on the same field:
///
/// ```compile_fail
/// use rod_validation::prelude::*;
///
/// #[derive(RodValidate)]
/// struct Both {
///     #[rod(
///         String { length: 3..=30 },
///         check = |s: &String| !s.is_empty(),
///         check_all = |s: &String| vec![]
///     )]
///     name: String,
/// }
/// ```

// Re-exported so that code generated by `#[derive(RodValidate)]` can build
// JSON Schemas without requiring `serde_json` to be a direct dependency of
// the deriving crate.
#[cfg(feature = "serde")]
pub use serde_json as __serde_json;

